    rejected_by character varying(200),
    rejected_at timestamp with time zone,
    cancellation_reason text,
    created_by character varying(200) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    row_version bigint DEFAULT 0 NOT NULL,
    selection_json jsonb DEFAULT '{}'::jsonb NOT NULL,
    quote_type character varying(20) DEFAULT 'NEW'::character varying NOT NULL,
    source_policy_id uuid,
    renewal_json jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT ck_quote_currency CHECK (((currency_code IS NULL) OR (currency_code ~ '^[A-Z]{3}$'::text))),
    CONSTRAINT ck_quote_dates CHECK (((valid_until IS NULL) OR (valid_until >= effective_date))),
    CONSTRAINT ck_quote_four_eyes CHECK (((approved_by IS NULL) OR (submitted_by IS NULL) OR ((approved_by)::text <> (submitted_by)::text))),
    CONSTRAINT ck_quote_renewal_object CHECK ((jsonb_typeof(renewal_json) = 'object'::text)),
    CONSTRAINT ck_quote_renewal_source CHECK ((((quote_type)::text = 'NEW'::text) OR (source_policy_id IS NOT NULL))),
    CONSTRAINT ck_quote_row_version CHECK ((row_version >= 0)),
    CONSTRAINT ck_quote_selection_object CHECK ((jsonb_typeof(selection_json) = 'object'::text)),
    CONSTRAINT ck_quote_status CHECK (((status)::text = ANY ((ARRAY['DRAFT'::character varying, 'READY'::character varying, 'IN_REVIEW'::character varying, 'APPROVED'::character varying, 'REJECTED'::character varying, 'EXPIRED'::character varying, 'CANCELLED'::character varying, 'BOUND'::character varying])::text[]))),
    CONSTRAINT ck_quote_type CHECK (((quote_type)::text = ANY ((ARRAY['NEW'::character varying, 'RENEWAL'::character varying])::text[])))
);


--
