    CONSTRAINT ck_quote_adjustment_kind CHECK (((kind)::text = ANY ((ARRAY['SURCHARGE_PERCENT'::character varying, 'DISCOUNT_PERCENT'::character varying, 'SURCHARGE_AMOUNT'::character varying, 'DISCOUNT_AMOUNT'::character varying])::text[]))),
    CONSTRAINT ck_quote_adjustment_member CHECK ((((scope)::text = 'MEMBER'::text) = (member_id IS NOT NULL))),
    CONSTRAINT ck_quote_adjustment_scope CHECK (((scope)::text = ANY ((ARRAY['QUOTE'::character varying, 'MEMBER'::character varying])::text[]))),
    CONSTRAINT ck_quote_adjustment_status CHECK (((status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'REMOVED'::character varying])::text[]))),
    CONSTRAINT ck_quote_adjustment_value CHECK ((value > (0)::numeric))
);


